INSERT INTO public.comments (
  id, publication_id, author_id, content, updated_at
) VALUES (
  'e0000001-0008-0000-0000-000000000008',
  'd1000001-0011-0000-0000-000000000011',
  'b1b1b1b1-0008-0000-0000-000000000008',
